import traceback
import wrapt


def ignore_exceptions(exceptions, result=None, logger_method=None):
    """
    *DEPRECATED*
    Use ute_common_util.decorators.exception.ignore_exceptions
    Remove date: July 1, 2017
    """
    @wrapt.decorator
    def wrapper(wrapped, instance, args, kwargs):
        """Wrapper"""
        try:
            return wrapped(*args, **kwargs)
        except Exception as e:
            return _Helper.ignore_exceptions(e, exceptions, result, logger_method)
    return wrapper


def ignore_exceptions_other_than(exceptions, result=None, logger_method=None):
    """
    *DEPRECATED*
    Use ute_common_util.decorators.exception.ignore_exceptions_other_than
    Remove date: July 1, 2017
    """
    @wrapt.decorator
    def wrapper(wrapped, instance, args, kwargs):
        """Wrapper"""
        try:
            return wrapped(*args, **kwargs)
        except Exception as e:
            _Helper.raise_if_exception_matches(e, exceptions)
            _Helper.log_traceback(logger_method)
            return result
    return wrapper


class _Helper(object):
    @classmethod
    def raise_if_exception_matches(cls, found_exception, expected_exceptions):
        """Method raise found_exception if type is as expected."""
        for each in expected_exceptions:
            if isinstance(found_exception, each):
                raise     # pylint: disable=misplaced-bare-raise

    @classmethod
    def ignore_exceptions(cls, found_exception, expected_exceptions, result, logger_method):
        """Method raise found_exception if found_exception is different than expected."""
        for each in expected_exceptions:
            if isinstance(found_exception, each):
                _Helper.log_traceback(logger_method)
                return result
        raise       # pylint: disable=misplaced-bare-raise

    @classmethod
    def log_traceback(cls, logger_method):
        """Log traceback."""
        if logger_method:
            logger_method(traceback.format_exc())
